<?php
require __DIR__ . '/inc/bootstrap.php';
$settings=site_settings();
$posts=load_json('posts.json',[]);
$q=trim($_GET['q']??'');
$tag=trim($_GET['tag']??'');
if($q!==''||$tag!==''){$posts=array_values(array_filter($posts,function($p)use($q,$tag){$ok=true;if($q!=='')$ok=stripos(($p['title']??'').' '.($p['content']??''),$q)!==false;if($ok&&$tag!=='')$ok=in_array($tag,$p['tags']??[],true);return $ok;}));}
?><!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($settings['site_name'])?></title><link rel="stylesheet" href="assets/style.css"></head><body><?php include __DIR__.'/inc/header.php'; ?><main class="container"><section class="hero card"><div class="status blink">● ONLINE</div><h1><?=e($settings['site_name'])?></h1><p><?=e($settings['tagline'])?></p><p class="announcement">&gt; <?=e($settings['announcement'])?></p></section><form class="search" method="get"><input name="q" value="<?=e($q)?>" placeholder="SEARCH DATA LOGS..."><button>SEARCH</button></form><h2 class="section-title">&gt;&gt; DATA LOGS</h2><?php if(!$posts): ?><div class="card">NO DATA FOUND</div><?php endif; ?><?php foreach(array_reverse($posts) as $p): ?><article class="card"><div class="post-meta">LOG-<?=e($p['id'])?> // <?=e($p['date']??'')?> // VIEWS <?=e($p['views']??0)?></div><a href="post.php?id=<?=urlencode($p['id'])?>"><div class="post-title">&gt; <?=e($p['title'])?></div></a><div><?=e(mb_substr($p['content'],0,120))?><?=mb_strlen($p['content'])>120?'...':''?></div><?php if(!empty($p['tags'])):?><div class="tags"><?php foreach($p['tags'] as $t):?><a href="?tag=<?=urlencode($t)?>">#<?=e($t)?></a><?php endforeach;?></div><?php endif;?></article><?php endforeach;?></main><?php include __DIR__.'/inc/footer.php'; ?></body></html>
